sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
	c.selectItem = function(idx) {
    var id = c.data.notes[idx].sys_id;
    console.log('Note IDwww: ' + id);
    $rootScope.noteID = id;
    $rootScope.$emit('selectNote', id);
  }

	$rootScope.$on('noteUpdated', function(event, updatedNote) {
		// Trouver l'index de la note mise à jour dans la liste
		var idx = c.data.notes.findIndex(function(note) {
			return note.sys_id === updatedNote.sys_id;
		});

		if (idx !== -1) {
			// Mettre à jour l'élément trouvé dans la liste
			c.data.notes[idx].title = updatedNote.title;
			// La description (tronquée) vient du corps mis à jour
			c.data.notes[idx].note = updatedNote.note; 

			console.log("Notes List updated entry for sys_id: " + updatedNote.sys_id);
		}
	});

};

sp_widget.script:
(function() {
	//create an array to populate with notes
	data.notes = [];
	var noteGR = new GlideRecord('x_snc_createnotes_note');
	noteGR.addQuery('user', gs.getUser().getID());
	noteGR.orderByDesc('sys_created_on');
	noteGR.query();
	while (noteGR.next()) {
		var noteObj = {};
		//use service portal helper method to get some display values
		$sp.getRecordDisplayValues(noteObj, noteGR, 'number,title,sys_id');
		//get the first 20 characters of the description
		noteObj.note = noteGR.getValue('note').slice(0,20);
		//push the populated obj into the array
		data.notes.push(noteObj);
	}
})();
